type IdempotencyResult struct {
	StatusCode   int
	Response     json.RawMessage
	Replay       bool
	FencingToken uint64
}

type idempotencyReservation struct {
	method, target, principal, digest string
	status                            *int
	response                          []byte
	reservedUntil                     time.Time
	fencingToken                      uint64
}

type Ledger struct{ pool *pgxpool.Pool }

